const promoter = ($input.all()[0] && $input.all()[0].json) || {};
const url = String(promoter.url_lista || 'https://www.taquilla.com/almeria');
return [{ json: { ...promoter, url_listado: url } }];

// Extrae los slugs únicos de /entradas/<slug> del HTML del índice /almeria.
// Devuelve N items (uno por slug) que el siguiente nodo iterará para hacer fetch.
const cheerio = require('cheerio');
const html = String(($json && ($json.data || $json.body)) || '');
if (!html) return [];

const $ = cheerio.load(html);
const ORIGEN = 'https://www.taquilla.com';
const slugs = new Set();

$('a[href]').each((_, a) => {
  const href = String($(a).attr('href') || '');
  // Aceptar solo /entradas/<slug-simple>/
  const m = href.match(/^\/entradas\/([a-z0-9-]+)\/?$/i);
  if (!m) return;
  slugs.add(m[1]);
});

return [...slugs].map(slug => ({
  json: {
    artista_slug: slug,
    artista_url: ORIGEN + '/entradas/' + slug,
  },
}));

// Recibe N respuestas HTML (1 por artista). De cada una extrae las sesiones
// usando schema.org microdata. Filtra por whitelist C15 (addressLocality).
const cheerio = require('cheerio');

const C15 = new Set([
  'almeria','nijar','tabernas','lucainena de las torres','turrillas',
  'huercal de almeria','viator','pechina','rioja','sorbas',
  'alhama de almeria','benahadux','santa fe de mondujar','finana',
  'abla','abrucena','tres villas las','las tres villas','nacimiento','gergal','gador'
]);

function municipioNorm(s) {
  return String(s == null ? '' : s)
    .normalize('NFD').replace(/[\u0300-\u036f]/g, '')
    .toLowerCase()
    .replace(/[\(\)\[\]\.,;:'"!\?\-–—\/]/g, ' ')
    .replace(/\s+/g, ' ').trim();
}

function detectarMunicipioC15(loc) {
  if (!loc) return null;
  const last = loc.split(',').pop().trim();
  let norm = municipioNorm(last);
  if (C15.has(norm)) return norm;
  if (/\btres villas\b/.test(norm)) return 'las tres villas';
  const sinProv = norm.replace(/\s+almeria$/, '').trim();
  if (sinProv !== norm && C15.has(sinProv)) return sinProv;
  return null;
}

function clean(t) { return String(t == null ? '' : t).replace(/\s+/g, ' ').trim(); }

const today = new Date();
const TODAY_ISO = today.toISOString().slice(0, 10);

const allInputs = $input.all();
const events = [];
const seenIds = new Set();

for (const item of allInputs) {
  const html = String((item.json && (item.json.data || item.json.body)) || '');
  if (!html) continue;
  const $ = cheerio.load(html);
  const artistaSlug = clean(item.json.artista_slug || '');
  const artistaUrl = clean(item.json.artista_url || '');

  // Cada sesión es un <li itemscope itemtype="https://schema.org/*Event">
  $('li[itemscope][itemtype]').each((_, e) => {
    const $e = $(e);
    const itemtype = $e.attr('itemtype') || '';
    if (!/Event$|Event\b/.test(itemtype)) return;
    if (/ListItem/.test(itemtype)) return;

    const name = clean($e.find('> meta[itemprop="name"], meta[itemprop="name"]').first().attr('content'));
    const url = clean($e.find('meta[itemprop="url"]').first().attr('content'));
    const startDate = clean($e.find('meta[itemprop="startDate"]').first().attr('content'));
    const endDate = clean($e.find('meta[itemprop="endDate"]').first().attr('content')) || startDate;
    const image = clean($e.find('meta[itemprop="image"]').first().attr('content'));
    const performer = clean($e.find('[itemprop="performer"] meta[itemprop="name"]').first().attr('content'));

    // Extraer location subobjeto.
    const $loc = $e.find('[itemprop="location"]').first();
    const venueName = clean($loc.find('meta[itemprop="name"]').first().attr('content'));
    const venueUrl = clean($loc.find('meta[itemprop="url"]').first().attr('content'));
    const streetAddr = clean($loc.find('meta[itemprop="streetAddress"]').first().attr('content'));
    const postalCode = clean($loc.find('meta[itemprop="postalCode"]').first().attr('content'));
    const addrLocality = clean($loc.find('meta[itemprop="addressLocality"]').first().attr('content'));
    const country = clean($loc.find('meta[itemprop="addressCountry"]').first().attr('content'));

    // Precio (oferta).
    let priceMin = 0;
    $e.find('[itemprop="offers"] [itemprop="price"], [itemprop="price"]').each((_, p) => {
      const v = parseFloat(clean($(p).attr('content') || $(p).text()));
      if (!isNaN(v) && v > 0 && (priceMin === 0 || v < priceMin)) priceMin = v;
    });

    // Filtros.
    if (!startDate) return;
    if (endDate && endDate < TODAY_ISO) return;

    // Filtro C15 sobre addressLocality.
    const muniNorm = detectarMunicipioC15(addrLocality);
    if (!muniNorm) return;

    // event_id: del ?event=<id> en url, o caer en slug+fecha.
    const idMatch = url.match(/[?&]event=(\d+)/);
    const numericId = idMatch ? idMatch[1] : '';
    const event_id = numericId
      ? 'taquilla_' + numericId
      : 'taquilla_' + artistaSlug + '_' + (startDate || '').replace(/-/g, '');
    if (seenIds.has(event_id)) return;
    seenIds.add(event_id);

    events.push({
      event_id,
      name,
      datetime_text: name,
      venue: venueName,
      event_url: url,
      cartel_url: image,
      slug: artistaSlug,
      api_id: numericId,
      itemtype,
      performer,
      fecha_inicio_listado: startDate,
      fecha_fin_listado: endDate,
      venue_url: venueUrl,
      venue_address: streetAddr,
      venue_postal_code: postalCode,
      venue_locality: addrLocality,
      venue_country: country,
      municipio_norm: muniNorm,
      precio_min: priceMin,
      artista_url: artistaUrl,
      es_espectaculo: true,
      estado_listado: 'A la venta',
    });
  });
}

return [{ json: { data: { data: { events } } } }];

const event = $json["data.data.events"];
if (!event || !event.name) return $json;

let result = String(event.name).trim();
result = result.replace(/Ñ/g, '__ENE_MAY__').replace(/ñ/g, '__ENE_MIN__');
result = result.normalize('NFD').replace(/[\u0300-\u036f]/g, '');
result = result.replace(/__ENE_MAY__/g, 'Ñ').replace(/__ENE_MIN__/g, 'ñ');
result = result.toUpperCase();
result = result.replace(/[^A-ZÑ0-9,.:+\- ]/g, '');
result = result.replace(/\s+/g, ' ').trim();
$json["data.data.events"].name = result;
return $json;

// Taquilla.com: el detalle ya se extrajo en ParsearSesiones (microdata schema.org).
// No necesitamos otro fetch — solo consolidamos desde payload_json del front.
const front = $json || {};
const fp = front.payload_json || {};

const event_id = front.event_id || fp.event_id || '';
const titulo = front.name || fp.name || '';
const event_url = front.event_url || fp.event_url || '';

const fecha_inicio = String(fp.fecha_inicio_listado || '');
const fecha_fin = String(fp.fecha_fin_listado || fecha_inicio);
const hora_inicio = '';  // taquilla no expone hora en startDate (solo YYYY-MM-DD)
const tipo_fecha = fecha_inicio
  ? (fecha_fin && fecha_fin !== fecha_inicio ? 'rango' : 'simple')
  : 'texto_no_parseable';

const venue = String(fp.venue || front.venue || '');
const venue_address = String(fp.venue_address || '');
const local = venue_address ? venue + ' — ' + venue_address : venue;

const precio_min = typeof fp.precio_min === 'number' ? fp.precio_min : 0;
const cartel_url = String(fp.cartel_url || '');

const payload = {
  fuente: 'taquilla_almeria',
  tipo_evento: String(fp.itemtype || '').replace('https://schema.org/', '').replace('Event', '').toUpperCase() || 'ESPECTACULO',
  ticketera: 'taquilla_com',
  ticketera_url: event_url,
  estado_listado: fp.estado_listado || 'A la venta',
  precio_min,
  precio_max: precio_min,
  precio_medio: precio_min,
  aforo_total: null,
  venue: {
    name: venue,
    full_address: venue_address,
    locality: fp.venue_locality || '',
    postal_code: fp.venue_postal_code || '',
    country: fp.venue_country || '',
    url: fp.venue_url || '',
  },
  municipio_norm: String(fp.municipio_norm || ''),
  performer: fp.performer || '',
  api_id: fp.api_id || '',
  artista_slug: fp.slug || '',
  artista_url: fp.artista_url || '',
  itemtype: fp.itemtype || '',
};

return {
  json: {
    event_id,
    titulo,
    titulo_original: titulo,
    observacion: '',
    datetime_text_original: front.datetime_text || '',
    fecha_inicio,
    fecha_fin,
    hora_inicio,
    tipo_fecha,
    num_sesiones_estimadas: fecha_inicio ? 1 : null,
    tiene_multiples_sesiones: false,
    precio_entradas: precio_min,
    precio_medio_entradas: precio_min,
    local,
    es_gratuito: precio_min === 0,
    cartel_url,
    screenshot_url: '',
    ticketera_url: event_url,
    payload_json: payload,
  },
};

function normalizeSegment(value, fallback = 'sin-valor') {
  const normalized = String(value || '')
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '')
    .replace(/[^A-Za-z0-9]+/g, '-')
    .replace(/^-+|-+$/g, '')
    .toLowerCase();
  return normalized || fallback;
}

function extractExtension(url, tipo) {
  const cleanUrl = String(url || '').split('?')[0];
  const match = cleanUrl.match(/\.([A-Za-z0-9]{2,5})$/);
  if (match) return match[1].toLowerCase();
  return tipo === 'screenshot' ? 'png' : 'jpg';
}

const eventId = String($json.event_id || '').trim();
const tipo = String($json.tipo || '').trim();
const titulo = String($json.titulo || '').trim();
const promotor = normalizeSegment($json.promotor, 'taquilla-almeria');
const anio = String($json.anio || '').trim() || 'sin-anio';
const tituloSlug = normalizeSegment(titulo, 'evento');
const eventSlug = eventId + '+' + tituloSlug;
const extension = extractExtension($json.url_origen, tipo);
const nombreArchivo = tipo + '.' + extension;
const dropboxFolder = '/0-CANCERBERO/EVENTOS/' + promotor + '/' + anio + '/' + eventSlug;

return {
  ...$json,
  promotor,
  anio,
  titulo_slug: tituloSlug,
  event_slug: eventSlug,
  nombre_archivo: nombreArchivo,
  dropbox_folder: dropboxFolder,
  dropbox_path: dropboxFolder + '/' + nombreArchivo,
};

